  "interactive-laptop": "<!-- Interactive Laptop Component: Digital Learning & Campus Life -->\n<section id=\"shop\" class=\"py-24 bg-[#FAF7F0] relative overflow-hidden\">\n  <div class=\"max-w-5xl mx-auto px-4 sm:px-6 lg:px-8 text-center\">\n    \n    <!-- Header -->\n    <div class=\"mb-12\">\n      <h2 class=\"font-display font-black text-4xl sm:text-6xl text-[#121212] uppercase tracking-tight\">\n        Pusat Belajar <span class=\"inline-block px-4 py-1.5 bg-[#121212] text-lime rounded-xl border-[2.5px] border-[#121212] brutal-shadow tilt-left transform\">Santri</span>\n      </h2>\n      <p class=\"font-cursive text-3xl sm:text-4xl text-[#E53935] font-bold mt-2\">\n        sarana belajar & kehidupan santri\n      </p>\n      <div class=\"mt-6 flex justify-center\">\n        <button data-open-modal=\"waitlist\" class=\"btn-tactile inline-flex items-center gap-3 px-6 py-2.5 rounded-full bg-lime text-[#121212] font-label font-bold text-xs uppercase tracking-wider border-[2px] border-[#121212] brutal-shadow-sm\">\n          <span>Jelajahi Aktivitas Pondok</span>\n          <span class=\"text-xs\">➔</span>\n        </button>\n      </div>\n    </div>\n\n    <!-- Interactive Laptop Surface Mockup -->\n    <div class=\"relative max-w-3xl mx-auto\">\n      \n      <!-- Tooltip Instruction -->\n      <div class=\"inline-flex items-center gap-2 px-4 py-1.5 rounded-full bg-white border-[2px] border-[#121212] brutal-shadow-sm font-label font-bold text-xs uppercase tracking-wider mb-4\">\n        <span>🎯</span>\n        <span>Geser stiker untuk menjelajahi aktivitas santri</span>\n      </div>\n\n      <!-- MacBook Lid Surface (Drop Area) -->\n      <div id=\"laptop-surface\" class=\"laptop-lid p-6 min-h-[460px] sm:min-h-[520px]\">\n        \n        <!-- Center Emblem Silhouette -->\n        <div class=\"absolute top-1/2 left-1/2 -translate-x-1/2 -translate-y-1/2 opacity-20 pointer-events-none\">\n          <img src=\"./assets/images/logo.png\" alt=\"Emblem BQC\" class=\"w-24 h-24 object-contain filter grayscale\">\n        </div>\n\n        <!-- Laptop Open Notch -->\n        <div class=\"laptop-notch\"></div>\n\n        <!-- DRAGGABLE STICKER 1: BQC Emblem -->\n        <div class=\"draggable-sticker w-20 h-auto top-8 left-8 tilt-left cursor-grab\" style=\"z-index: 10;\">\n          <img src=\"./assets/images/logo.png\" alt=\"Stiker Emblem BQC\" class=\"w-full h-auto pointer-events-none drop-shadow-[3px_3px_0px_#121212]\">\n        </div>\n\n        <!-- DRAGGABLE STICKER 2: Campus Bus / Van -->\n        <div class=\"draggable-sticker w-36 h-auto bottom-8 left-12 tilt-right cursor-grab\" style=\"z-index: 11;\">\n          <img src=\"./assets/images/sticker-van.svg\" alt=\"Stiker Mobil Operasional Pesantren\" class=\"w-full h-auto pointer-events-none drop-shadow-[3px_3px_0px_#121212]\">\n        </div>\n\n        <!-- DRAGGABLE STICKER 3: Trophy -->\n        <div class=\"draggable-sticker w-16 h-auto top-28 left-48 tilt-left cursor-grab\" style=\"z-index: 8;\">\n          <img src=\"./assets/images/sticker-trophy.svg\" alt=\"Stiker Piala Prestasi\" class=\"w-full h-auto pointer-events-none drop-shadow-[3px_3px_0px_#121212]\">\n        </div>\n\n        <!-- DRAGGABLE STICKER 4: Starburst \"Bite Learn Repeat\" -->\n        <div class=\"draggable-sticker w-24 h-auto top-12 right-40 tilt-right cursor-grab\" style=\"z-index: 9;\">\n          <img src=\"./assets/images/sticker-starburst.svg\" alt=\"Stiker Bintang Sertifikasi\" class=\"w-full h-auto pointer-events-none drop-shadow-[3px_3px_0px_#121212]\">\n        </div>\n\n        <!-- DRAGGABLE STICKER 5: \"TAHFIZH AL-QUR'AN\" Badge -->\n        <div class=\"draggable-sticker px-4 py-2 bg-lime text-[#121212] rounded-xl border-[2.5px] border-[#121212] brutal-shadow font-display font-black text-sm uppercase top-16 right-10 tilt-right cursor-grab\" style=\"z-index: 12;\">\n          30 JUZ TAHFIZH & SANAD\n        </div>\n\n        <!-- DRAGGABLE STICKER 6: Lightning Bolt -->\n        <div class=\"draggable-sticker w-14 h-auto bottom-20 right-48 tilt-left cursor-grab\" style=\"z-index: 7;\">\n          <img src=\"./assets/images/sticker-lightning.svg\" alt=\"Stiker Petir Energi\" class=\"w-full h-auto pointer-events-none drop-shadow-[3px_3px_0px_#121212]\">\n        </div>\n\n        <!-- DRAGGABLE STICKER 7: Soda Cup -->\n        <div class=\"draggable-sticker w-14 h-auto bottom-8 right-24 tilt-right cursor-grab\" style=\"z-index: 13;\">\n          <img src=\"./assets/images/sticker-soda.svg\" alt=\"Stiker Minuman Sehat\" class=\"w-full h-auto pointer-events-none drop-shadow-[3px_3px_0px_#121212]\">\n        </div>\n\n        <!-- DRAGGABLE STICKER 8: Graduation Cap -->\n        <div class=\"draggable-sticker w-16 h-auto bottom-24 left-64 tilt-left cursor-grab\" style=\"z-index: 6;\">\n          <img src=\"./assets/images/sticker-gradcap.svg\" alt=\"Stiker Topi Wisuda\" class=\"w-full h-auto pointer-events-none drop-shadow-[3px_3px_0px_#121212]\">\n        </div>\n\n      </div>\n\n    </div>\n\n  </div>\n</section>\n",
